    /**
     * Singleton handle — all data methods are static.
     */
    public static function instance(): self
    {
        return self::$singleton ??= new self();
    }

    /**
     * @return array<string,mixed>
     */
    private static function src(): array
    {
        return self::$data;
    }

    private static function getString(string $key, string $default = ''): string
    {
        if (! array_key_exists($key, self::SCHEMA)) {
            throw new UnknownConfigKeyException($key, 'getString');
        }
        $v = self::src()[$key] ?? $default;
        if (is_string($v)) {
            return $v;
        }
        if (is_scalar($v)) {
            return (string) $v;
        }
        return $default;
    }

    /**
     * Same as getString, but the caller asserts the *default* is
     * non-empty-string. Lets typed accessors declare
     * `@return non-empty-string` without per-call-site narrowing.
     *
     * @param non-empty-string $default
     * @return non-empty-string
     */
    private static function getNonEmptyString(string $key, string $default): string
    {
        $value = self::getString($key, $default);
        return $value !== '' ? $value : $default;
    }

    private static function getInt(string $key, int $default = 0): int
    {
        if (! array_key_exists($key, self::SCHEMA)) {
            throw new UnknownConfigKeyException($key, 'getInt');
        }
        $v = self::src()[$key] ?? $default;
        if (is_int($v)) {
            return $v;
        }
        if (is_scalar($v)) {
            return (int) $v;
        }
        return $default;
    }

    private static function getBool(string $key, bool $default = false): bool
    {
        if (! array_key_exists($key, self::SCHEMA)) {
            throw new UnknownConfigKeyException($key, 'getBool');
        }
        $v = self::src()[$key] ?? $default;
        return (bool) $v;
    }

