    /**
     * Coerce a raw `order_by*` config value into a list of validated
     * field+direction entries; drop anything that doesn't fit the shape or
     * has a non-ASC/DESC direction.
     *
     * @param array<mixed> $value
     * @return list<array{field: string, dir: 'ASC'|'DESC'}>
     */
    private static function filterOrderEntries(array $value): array
    {
        $out = [];
        foreach ($value as $entry) {
            if (! is_array($entry)) {
                continue;
            }
            $field = $entry['field'] ?? null;
            $dir = $entry['dir'] ?? null;
            if (! is_string($field) || ! is_string($dir)) {
                continue;
            }
            $dir = strtoupper($dir);
            if ($dir !== 'ASC' && $dir !== 'DESC') {
                continue;
            }
            $out[] = [
                'field' => $field,
                'dir' => $dir,
            ];
        }
        return $out;
    }

