    /**
     * Return all config values with sensitive entries redacted. Intended
     * for safe use in error-handler logs and diagnostic output.
     *
     * @return array<string,mixed>
     */
    public static function dumpForLog(): array
    {
        $out = [];
        foreach (self::$data as $key => $value) {
            $out[$key] = (self::SCHEMA[$key]['sensitive'] ?? false) === true
                ? str_repeat('*', 8)
                : $value;
        }
        return $out;
    }

    public static function has(string $key): bool
    {
        return array_key_exists($key, self::src());
    }

    public static function delete(string $key): void
    {
        unset(self::$data[$key]);
    }

    /**
     * Transient runtime override. Does not persist to DB (P14).
     */
    public static function override(string $key, mixed $value): void
    {
        self::$data[$key] = $value;
    }

